@Component("channel-handler")
@ProcessingGroup("channel-processing-group")
public class ChannelEventHandler {
	
	// core constructor
	ChannelEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateChannelEvent
     */
    @EventHandler
    public void handle( CreateChannelEvent event) {
        entityManager.persist(new Channel(event.getChannelId(), event.getName(), event.getChannelCode(), event.getLocale(), event.getDomain(), event.getAsActive(), event.getDefaultCurrency(), event.getMerchant(), event.getCatalogs(), event.getPromotions(), event.getShippingMethods(), event.getPaymentProviders(), event.getChannelType()));
    }

    /*
     * @param	event UpdateChannelEvent
     */
    @EventHandler
    public Channel handle( UpdateChannelEvent event) {
    	entityManager.merge(new Channel(event.getChannelId(), event.getName(), event.getChannelCode(), event.getLocale(), event.getDomain(), event.getAsActive(), event.getDefaultCurrency(), event.getMerchant(), event.getCatalogs(), event.getPromotions(), event.getShippingMethods(), event.getPaymentProviders(), event.getChannelType()));
    }
    
    /*
     * @param	event DeleteChannelEvent
     */
    @EventHandler
    public void on( DeleteChannelEvent event) {
    	Channel entity = new Channel();
   
    	// ------------------------------------------
    	// apply the ChannelId
    	// ------------------------------------------
    	entity.setChannelId( event.getChannelId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ChannelRepository channelEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ChannelEventHandler.class.getName());

}
